namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    MinReductionOverADimensionCustomTilingData tiling;

    const gert::Shape* in_shape_ptr = context->GetInputShape(0);
    auto origin_shape = in_shape_ptr->GetOriginShape();
    uint64_t totalLength = origin_shape.GetShapeSize();

    int64_t dimNum = origin_shape.GetDimNum();
    if (dimNum <= 0) {
        return ge::GRAPH_FAILED;
    }
    uint64_t reduceLen = static_cast<uint64_t>(origin_shape.GetDim(dimNum - 1));
    uint64_t outerCount = (reduceLen == 0) ? 0 : (totalLength / reduceLen);

    // 设置 block 数量（可根据实际平台调整）
    context->SetBlockDim(8);

    tiling.set_totalLength(static_cast<uint32_t>(totalLength));
    tiling.set_outerCount(static_cast<uint32_t>(outerCount));
    tiling.set_reduceLen(static_cast<uint32_t>(reduceLen));

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 本算子不需要额外 workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

